using LINGYUN.Abp.WeChat.Common.Messages;
using System.Xml.Serialization;
using Volo.Abp.EventBus;

namespace LINGYUN.Abp.WeChat.Official.Messages.Models;
/// <summary>
/// Picture message
/// </summary>
[EventName("picture")]
public class PictureMessage : WeChatOfficialGeneralMessage
{
    /// <summary>
    /// Image link (generated by the system)
    /// </summary>
    [XmlElement("PicUrl")]
    public string PicUrl { get; set; } = default!;
    /// <summary>
    /// Image message media id, you can call the temporary material interface to pull data.
    /// </summary>
    [XmlElement("MediaId")]
    public string MediaId { get; set; } = default!;
    public override WeChatMessageEto ToEto()
    {
        return new WeChatOfficialGeneralMessageEto<PictureMessage>(this);
    }
}
